// MUST be the very first thing that runs
process.env.TZ = 'America/Denver';

import assert from 'node:assert';
import { daysUntil, dueDayOfMonth } from './duedates';

// Date-only values must be interpreted as calendar dates, not UTC instants.
assert.strictEqual(dueDayOfMonth('2026-03-09'), 9, `dueDayOfMonth got ${dueDayOfMonth('2026-03-09')}, expected 9`);
assert.strictEqual(daysUntil('2026-03-10', '2026-03-09'), 1, `daysUntil got ${daysUntil('2026-03-10', '2026-03-09')}, expected 1`);

console.log('TZ=' + process.env.TZ + ': all tests passed');

