function parseISODate(s: string): { y: number; m: number; d: number } {
  // dates are 'YYYY-MM-DD'
  const [y, m, d] = s.split('-').map(Number);
  return { y, m, d };
}

export function daysUntil(dueDate: string, today: string): number {
  const due = parseISODate(dueDate);
  const now = parseISODate(today);
  // Pure integer math on UTC-anchored calendar dates: no local-timezone
  // interpretation ever enters the picture.
  const dueUTC = Date.UTC(due.y, due.m - 1, due.d);
  const nowUTC = Date.UTC(now.y, now.m - 1, now.d);
  return Math.round((dueUTC - nowUTC) / 86400000);
}

export function dueDayOfMonth(dueDate: string): number {
  const { y, m, d } = parseISODate(dueDate);
  // Local constructor with explicit components: the date is exactly
  // midnight of that calendar day in whatever zone we're running in,
  // so getDate() round-trips to the same day-of-month everywhere.
  return new Date(y, m - 1, d).getDate();
}

